<?php require_once '../functions.php';requireAdmin();$pageTitle='Users';
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=$pdo->prepare("UPDATE users SET status=0 WHERE id=?");$s->execute([$id]);redirect('users.php');}
$search=trim($_GET['search']??'');$sql="SELECT * FROM users WHERE 1";$params=[];if($search){$sql.=" AND (name LIKE ? OR email LIKE ?)";$params=["%$search%","%$search%"];} $sql.=" ORDER BY created_at DESC";$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();require 'header.php';?>
<div class="d-flex justify-content-between mb-3"><h1>Users</h1><form class="d-flex"><input class="form-control" name="search" placeholder="Search users" value="<?=e($search)?>"><button class="btn btn-dark ms-2">Search</button></form></div>
<div class="table-responsive"><table class="table bg-white"><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Mobile</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['mobile'])?></td><td><?= $r['status']?'Active':'Inactive' ?></td><td><?php if($r['status']):?><a class="btn btn-sm btn-outline-danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Deactivate this user?')">Deactivate</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php require 'footer.php';?>
